-- PanoplySuite_RouteData: travel data for Panoply Suite's route planner (0.6.0, SPEC section 21).
-- Flight nodes and paths, ships, zeppelins and the Deeprun Tram, innkeepers and zone rectangles.
-- Generated by Panoply Suite's tools/build_routedata.py from the client DB2 tables (wago.tools) and the
-- VMaNGOS world database (GPL-2.0-or-later). Plain Lua tables, no code from any other add-on.
-- Distributed under the GNU GPL v3, see LICENSE and NOTICE.md.
local RD = {}
_G.PanoplySuiteRouteData = RD
RD.apiVersion = 1
RD.version = "0.9.9.6"
RD.source = "wago.tools DB2 (client tables) + VMaNGOS world DB (GPL-2.0-or-later)"
-- Decode one flight trail string "x,y x,y ..." into { {x, y}, ... } (cached; on demand).
local cache = setmetatable({}, { __mode = "k" })
function RD.Trail(leg)
  local t = cache[leg]
  if t then return t end
  t = {}
  for x, y in leg[5]:gmatch("(-?%d+),(-?%d+)") do t[#t + 1] = { tonumber(x), tonumber(y) } end
  cache[leg] = t
  return t
end
